import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    return (major, minor, patch, pre)

def _pre_ids(pre):
    return pre.split('.')

def _cmp_id(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    return (a > b) - (a < b)

def _compare(v1, v2):
    M1, m1, p1, pre1 = _parse(v1)
    M2, m2, p2, pre2 = _parse(v2)
    for a, b in ((M1, M2), (m1, m2), (p1, p2)):
        if a != b:
            return -1 if a < b else 1
    if pre1 is None and pre2 is None:
        return 0
    if pre1 is None:
        return 1
    if pre2 is None:
        return -1
    ids1 = _pre_ids(pre1)
    ids2 = _pre_ids(pre2)
    for a, b in zip(ids1, ids2):
        c = _cmp_id(a, b)
        if c != 0:
            return c
    if len(ids1) != len(ids2):
        return -1 if len(ids1) < len(ids2) else 1
    return 0

def semver_sort(versions):
    indexed = list(enumerate(versions))
    def cmp(a, b):
        c = _compare(a[1], b[1])
        if c != 0:
            return c
        return a[0] - b[0]
    indexed.sort(key=functools.cmp_to_key(cmp))
    return [v for _, v in indexed]

